//! Native Go SDK generation for Poolster.
//!
//! This crate consumes only the neutral [`Api`] model.  It deliberately does
//! not know about OpenAPI files, the Go sidecar, or a JavaScript runtime.

use std::{
    collections::{BTreeMap, BTreeSet},
    fmt::Write,
};

use anyhow::{Result, bail};
use poolster_core::{
    AdditionalProperties, Api, GeneratedFile, GeneratedTree, Operation, OperationParameter, Schema,
    SchemaKind, SchemaValue, SdkClientStyle,
};

const NOTICE: &str = "// Code generated by Poolster. DO NOT EDIT.\n";

mod composition;
#[cfg(test)]
mod extension_compat_tests;
mod layout;
mod operation_tests;
mod page_pagination;
mod symbols;
pub use operation_tests::{OperationTests, operation_tests};
pub mod providers;
mod response_validation;
pub use providers::{client, models, operations, roundtrip_tests, transport};

fn render_sdk(
    api: &Api,
    output_dir: &str,
    package_name: Option<&str>,
    client_style: SdkClientStyle,
    jobs: usize,
) -> Result<GeneratedTree> {
    let prepared = symbols::prepare(api);
    let api = prepared.as_ref();
    let output_dir = normalized_output_dir(output_dir)?;
    let composed = composition::models(api);
    let schemas = composed.as_deref().unwrap_or(&api.schemas);
    let package = package_name
        .map(go_package_name)
        .filter(|name| !name.is_empty())
        .unwrap_or_else(|| go_package_name(&api.name));
    if package.is_empty() {
        bail!("a Go package name could not be derived from the API name")
    }

    let module = go_module_name(package_name.unwrap_or(&api.name));
    let mut tree = GeneratedTree::default();
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "go.mod"),
        render_go_mod(&module),
    )?)?;
    layout::generate(
        &mut tree,
        api,
        schemas,
        &output_dir,
        &package,
        client_style,
        jobs,
    )?;
    tree.insert(GeneratedFile::new(
        output_path(&output_dir, "README.md"),
        render_readme(api, client_style),
    )?)?;
    if api.operations.iter().any(has_multipart) {
        tree.insert(GeneratedFile::new(
            output_path(&output_dir, "MULTIPART.md"),
            include_str!("../templates/multipart.md.tmpl"),
        )?)?;
    }
    if client_style == SdkClientStyle::Namespaced {
        tree.insert(GeneratedFile::new(
            output_path(&output_dir, "STYLE_GUIDE.md"),
            render_style_guide(api),
        )?)?;
    }
    Ok(tree)
}

fn normalized_output_dir(output_dir: &str) -> Result<String> {
    let output_dir = output_dir.trim_matches('/');
    if output_dir.is_empty() || output_dir == "." {
        return Ok(String::new());
    }
    if output_dir.split('/').any(|component| component == "..") {
        bail!("Go SDK output directory cannot contain parent-directory components")
    }
    Ok(output_dir.to_owned())
}

fn output_path(output_dir: &str, file: &str) -> String {
    if output_dir.is_empty() {
        file.to_owned()
    } else {
        format!("{output_dir}/{file}")
    }
}

fn render_go_mod(module: &str) -> String {
    format!("module {module}\n\ngo 1.22\n")
}

fn model_field_names(fields: &[poolster_core::Field]) -> BTreeMap<String, String> {
    let reserved: BTreeSet<String> = fields
        .iter()
        .map(|field| go_type_name(&field.name))
        .collect();
    let mut used = BTreeSet::new();
    fields
        .iter()
        .map(|field| {
            let base = go_type_name(&field.name);
            let mut name = base.clone();
            let mut suffix = 2;
            while used.contains(&name) || (name != base && reserved.contains(&name)) {
                name = format!("{base}{suffix}");
                suffix += 1;
            }
            used.insert(name.clone());
            (field.name.clone(), name)
        })
        .collect()
}

fn valid_json_tag_name(name: &str) -> bool {
    !name.is_empty()
        && name != "-"
        && name
            .chars()
            .all(|ch| ch.is_ascii_alphanumeric() || "!#$%&()*+./:;<=>?@[]^_{|}~ -".contains(ch))
}

fn render_schema(output: &mut String, schema: &Schema) {
    let name = go_type_name(&schema.name);
    match &schema.value.kind {
        SchemaKind::Object {
            fields,
            additional_properties,
        } => {
            let field_names = model_field_names(fields);
            let custom_fields: Vec<_> = fields
                .iter()
                .filter(|field| !valid_json_tag_name(&field.name))
                .collect();
            let _ = writeln!(output, "type {name} struct {{");
            for field in fields {
                let field_name = &field_names[&field.name];
                let mut field_type = go_type(&field.value);
                if !field.required && !field_type.starts_with('*') {
                    field_type = format!("*{field_type}");
                }
                let omitempty = if field.required { "" } else { ",omitempty" };
                let tag = if valid_json_tag_name(&field.name) {
                    format!("{}{omitempty}", field.name)
                } else {
                    "-".into()
                };
                let _ = writeln!(output, "\t{field_name} {field_type} `json:\"{tag}\"`");
            }
            let extra_type = match additional_properties {
                AdditionalProperties::Schema { value } => Some(go_type(value)),
                AdditionalProperties::Any | AdditionalProperties::Unspecified => {
                    Some("json.RawMessage".into())
                }
                AdditionalProperties::Forbidden => None,
            };
            // Preserve declared wire fields and allocate the synthetic extension bag separately.
            let mut extra_name = "AdditionalProperties".to_owned();
            let mut suffix = 2;
            while field_names.values().any(|name| *name == extra_name) {
                extra_name = format!("AdditionalProperties{suffix}");
                suffix += 1;
            }
            let nullable = fields
                .iter()
                .filter(|field| !field.required && (field.value.nullable || field.value.nullish))
                .collect::<Vec<_>>();
            if let Some(extra_type) = &extra_type {
                let _ = writeln!(
                    output,
                    "\t{extra_name} map[string]{extra_type} `json:\"-\"`"
                );
            }
            if !nullable.is_empty() {
                output.push_str("\tpoolsterNullFields map[string]bool\n");
            }
            output.push_str("}\n");
            if extra_type.is_some() || !nullable.is_empty() || !custom_fields.is_empty() {
                let _ = writeln!(
                    output,
                    "func (model *{name}) UnmarshalJSON(data []byte) error {{\n type plain {name}; var decoded plain; if err:=json.Unmarshal(data,&decoded);err!=nil {{return err}}; *model={name}(decoded)\n var fields map[string]json.RawMessage; if err:=json.Unmarshal(data,&fields);err!=nil {{return err}}"
                );
                for field in &custom_fields {
                    let key = serde_json::to_string(&field.name).unwrap();
                    let ident = &field_names[&field.name];
                    let _ = writeln!(
                        output,
                        "if raw,ok:=fields[{key}];ok {{if err:=json.Unmarshal(raw,&model.{ident});err!=nil {{return err}}}}"
                    );
                }
                if !nullable.is_empty() {
                    output.push_str("model.poolsterNullFields=map[string]bool{}\n");
                    for field in &nullable {
                        let key = serde_json::to_string(&field.name).unwrap();
                        let _ = writeln!(
                            output,
                            "if raw,ok:=fields[{key}];ok && string(raw)==\"null\" {{model.poolsterNullFields[{key}]=true}}"
                        );
                    }
                }
                if let Some(extra_type) = &extra_type {
                    let _ = writeln!(output, "model.{extra_name}=map[string]{extra_type}{{}}");
                    for field in fields {
                        let key = serde_json::to_string(&field.name).unwrap();
                        let _ = writeln!(output, "delete(fields,{key})");
                    }
                    let _ = writeln!(
                        output,
                        "for key,raw:=range fields {{var value {extra_type};if err:=json.Unmarshal(raw,&value);err!=nil {{return err}};model.{extra_name}[key]=value}}"
                    );
                }
                output.push_str("return nil\n}\n");
                let _ = writeln!(
                    output,
                    "func (model {name}) MarshalJSON() ([]byte,error) {{\n type plain {name};encoded,err:=json.Marshal(plain(model));if err!=nil {{return nil,err}};var fields map[string]json.RawMessage;if err:=json.Unmarshal(encoded,&fields);err!=nil {{return nil,err}}"
                );
                for field in &custom_fields {
                    let key = serde_json::to_string(&field.name).unwrap();
                    let ident = &field_names[&field.name];
                    if !field.required {
                        let _ = writeln!(output, "if model.{ident}!=nil {{");
                    }
                    let _ = writeln!(
                        output,
                        "raw{ident},err:=json.Marshal(model.{ident});if err!=nil {{return nil,err}};fields[{key}]=raw{ident}"
                    );
                    if !field.required {
                        output.push_str("}\n");
                    }
                }
                if extra_type.is_some() {
                    let _ = writeln!(
                        output,
                        "for key,value:=range model.{extra_name} {{if _,exists:=fields[key];exists {{continue}};raw,err:=json.Marshal(value);if err!=nil {{return nil,err}};fields[key]=raw}}\n"
                    );
                }
                for field in &nullable {
                    let key = serde_json::to_string(&field.name).unwrap();
                    let ident = &field_names[&field.name];
                    let _ = writeln!(
                        output,
                        "if model.poolsterNullFields[{key}] && model.{ident}==nil {{fields[{key}]=json.RawMessage(\"null\")}}"
                    );
                }
                output.push_str("return json.Marshal(fields)\n}\n");
            }
        }
        SchemaKind::String if !schema.value.enum_values.is_empty() => {
            let _ = writeln!(output, "type {name} string\n");
            output.push_str("const (\n");
            let preferred: Vec<_> = schema
                .value
                .enum_values
                .iter()
                .map(|value| format!("{name}{}", go_type_name(value.as_str().unwrap_or_default())))
                .collect();
            let reserved: BTreeSet<_> = preferred.iter().cloned().collect();
            let mut used = BTreeSet::new();
            for (index, value) in schema.value.enum_values.iter().enumerate() {
                let value = value.as_str().unwrap_or_default();
                let base = &preferred[index];
                let mut constant = base.clone();
                let mut suffix = 2;
                while used.contains(&constant)
                    || (constant != *base && reserved.contains(&constant))
                {
                    constant = format!("{base}{suffix}");
                    suffix += 1;
                }
                used.insert(constant.clone());
                let _ = writeln!(output, "\t{constant} {name} = {value:?}");
                if value.is_empty() {
                    let _ = writeln!(output, "\t_ = {index}");
                }
            }
            output.push_str(")\n");
        }
        _ => {
            let _ = writeln!(output, "type {name} = {}", go_type(&schema.value));
        }
    }
}

fn has_multipart(operation: &Operation) -> bool {
    operation.request_body.as_ref().is_some_and(|body| {
        body.media_types.iter().any(|media| {
            media
                .content_type
                .split(';')
                .next()
                .unwrap_or("")
                .trim()
                .to_ascii_lowercase()
                .starts_with("multipart/")
        })
    })
}

fn render_runtime(api: &Api, package: &str, client_style: SdkClientStyle) -> String {
    let resources = resource_operations(api);
    let facades = resource_facade_names(&resources);
    let facade_fields = if client_style == SdkClientStyle::Namespaced {
        resources
            .keys()
            .map(|resource| {
                let facade = &facades[resource];
                format!("\t{facade} *{facade}Service\n")
            })
            .collect::<String>()
    } else {
        String::new()
    };
    let facade_setup = if client_style == SdkClientStyle::Namespaced {
        resources
            .keys()
            .map(|resource| {
                let facade = &facades[resource];
                format!("\tclient.{facade} = &{facade}Service{{client: client}}\n")
            })
            .collect::<String>()
    } else {
        String::new()
    };
    let mut output = format!(
        "{NOTICE}\npackage {package}\n\nimport (\n\t\"bytes\"\n\t\"context\"\n\t\"encoding/json\"\n\t\"fmt\"\n\t\"io\"\n\t\"net/http\"\n\t\"net/url\"\n\t\"reflect\"\n\t\"strings\"\n)\n\n// ClientConfig configures a generated API client.\ntype ClientConfig struct {{\n\tBaseURL      string\n\tAPIKey       string\n\tAPIKeyHeader string\n\tAPIKeyPrefix string\n\tHTTPClient   *http.Client\n}}\n\n// Client is safe for concurrent use after construction.\ntype Client struct {{\n\tbaseURL      string\n\tapiKey       string\n\tapiKeyHeader string\n\tapiKeyPrefix string\n\thttpClient   *http.Client\n{facade_fields}}}\n\n// NewClient builds a client from explicit configuration. BaseURL is required.\nfunc NewClient(config ClientConfig) (*Client, error) {{\n\tbaseURL := strings.TrimRight(config.BaseURL, \"/\")\n\tif baseURL == \"\" {{\n\t\treturn nil, fmt.Errorf(\"poolster: BaseURL is required\")\n\t}}\n\theader := config.APIKeyHeader\n\tif header == \"\" {{\n\t\theader = \"Authorization\"\n\t}}\n\thttpClient := config.HTTPClient\n\tif httpClient == nil {{\n\t\thttpClient = http.DefaultClient\n\t}}\n\tclient := &Client{{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient}}\n{facade_setup}\treturn client, nil\n}}\n\n// APIError describes a non-success HTTP response.\ntype APIError struct {{\n\tStatusCode int\n\tBody       string\n}}\n\nfunc (errorResponse *APIError) Error() string {{\n\treturn fmt.Sprintf(\"poolster: API request failed with status %d: %s\", errorResponse.StatusCode, errorResponse.Body)\n}}\n\nfunc (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {{\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 {{\n\t\tendpoint += \"?\" + query.Encode()\n\t}}\n\tvar reader io.Reader\n\tif body != nil {{\n\t\tencoded, err := json.Marshal(body)\n\t\tif err != nil {{\n\t\t\treturn nil, fmt.Errorf(\"poolster: encode request body: %w\", err)\n\t\t}}\n\t\treader = bytes.NewReader(encoded)\n\t}}\n\trequest, err := http.NewRequestWithContext(ctx, method, endpoint, reader)\n\tif err != nil {{\n\t\treturn nil, fmt.Errorf(\"poolster: build request: %w\", err)\n\t}}\n\trequest.Header.Set(\"Accept\", \"application/json\")\n\tif body != nil {{\n\t\trequest.Header.Set(\"Content-Type\", \"application/json\")\n\t}}\n\tfor name, values := range headers {{\n\t\tfor _, value := range values {{\n\t\t\trequest.Header.Add(name, value)\n\t\t}}\n\t}}\n\tif client.apiKey != \"\" {{\n\t\tcredential := client.apiKey\n\t\tif client.apiKeyPrefix != \"\" {{\n\t\t\tcredential = client.apiKeyPrefix + \" \" + credential\n\t\t}}\n\t\trequest.Header.Set(client.apiKeyHeader, credential)\n\t}}\n\treturn request, nil\n}}\n\nfunc (client *Client) do(request *http.Request, destination any) error {{\n\tresponse, err := client.httpClient.Do(request)\n\tif err != nil {{\n\t\treturn fmt.Errorf(\"poolster: execute request: %w\", err)\n\t}}\n\tdefer response.Body.Close()\n\tif response.StatusCode < http.StatusOK || response.StatusCode >= http.StatusMultipleChoices {{\n\t\tbody, _ := io.ReadAll(io.LimitReader(response.Body, 1<<20))\n\t\treturn &APIError{{StatusCode: response.StatusCode, Body: string(body)}}\n\t}}\n\tif destination == nil || response.StatusCode == http.StatusNoContent {{\n\t\treturn nil\n\t}}\n\tif err := json.NewDecoder(response.Body).Decode(destination); err != nil && err != io.EOF {{\n\t\treturn fmt.Errorf(\"poolster: decode response: %w\", err)\n\t}}\n\treturn nil\n}}\n\nfunc addQuery(query url.Values, name string, value any) error {{\n\tif value == nil {{\n\t\treturn nil\n\t}}\n\treflected := reflect.ValueOf(value)\n\tif reflected.Kind() == reflect.Pointer {{\n\t\tif reflected.IsNil() {{\n\t\t\treturn nil\n\t\t}}\n\t\treturn addQuery(query, name, reflected.Elem().Interface())\n\t}}\n\tif reflected.Kind() == reflect.Slice || reflected.Kind() == reflect.Array {{\n\t\tfor index := 0; index < reflected.Len(); index++ {{\n\t\t\tif err := addQuery(query, name, reflected.Index(index).Interface()); err != nil {{\n\t\t\t\treturn err\n\t\t\t}}\n\t\t}}\n\t\treturn nil\n\t}}\n\tswitch value.(type) {{\n\tcase string, bool, int, int8, int16, int32, int64, uint, uint8, uint16, uint32, uint64, float32, float64:\n\t\tquery.Add(name, fmt.Sprint(value))\n\t\treturn nil\n\tdefault:\n\t\tencoded, err := json.Marshal(value)\n\t\tif err != nil {{\n\t\t\treturn fmt.Errorf(\"poolster: encode query %s: %w\", name, err)\n\t\t}}\n\t\tquery.Add(name, string(encoded))\n\t\treturn nil\n\t}}\n\n"
    );
    output = output.replace(
        "func (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 {\n\t\tendpoint += \"?\" + query.Encode()\n\t}\n\tvar reader io.Reader",
        "func (client *Client) newRequest(ctx context.Context, method, path string, query url.Values, headers http.Header, body any) (*http.Request, error) {\n\tendpoint := client.baseURL + path\n\tif len(query) > 0 { endpoint += \"?\" + query.Encode() }\n\treturn client.newRequestURL(ctx, method, endpoint, headers, body)\n}\n\n// newPaginationRequest is private on purpose: a generated pager may follow\n// only a same-origin URL supplied by its declared response contract. It still\n// uses the normal request builder, so auth, caller headers, and body encoding\n// cannot be bypassed by a continuation link.\nfunc (client *Client) newPaginationRequest(ctx context.Context, method, continuation string, headers http.Header, body any) (*http.Request, error) {\n\tbase, err := url.Parse(client.baseURL)\n\tif err != nil { return nil, fmt.Errorf(\"poolster: parse BaseURL: %w\", err) }\n\tnext, err := url.Parse(continuation)\n\tif err != nil { return nil, fmt.Errorf(\"poolster: parse pagination URL: %w\", err) }\n\tendpoint := base.ResolveReference(next)\n\tif endpoint.Scheme != base.Scheme || endpoint.Host != base.Host {\n\t\treturn nil, fmt.Errorf(\"poolster: pagination URL must remain on the configured API origin\")\n\t}\n\treturn client.newRequestURL(ctx, method, endpoint.String(), headers, body)\n}\n\nfunc (client *Client) newRequestURL(ctx context.Context, method, endpoint string, headers http.Header, body any) (*http.Request, error) {\n\tvar reader io.Reader",
    );
    // A spec can legitimately define a model called APIError. Keep the
    // transport error private so it can never collide with exported models.
    output = output.replace("APIError", "poolsterAPIError");
    // The format literal closes `addQuery`'s switch; this closes the helper.
    output.push_str("}\n\n");

    if api.operations.iter().any(|operation| {
        cursor_pagination(api, operation).is_some()
            || page_pagination::supported(api, operation)
            || offset_pagination(api, operation).is_some()
            || url_pagination(api, operation).is_some()
    }) {
        output.push_str(PAGINATION_RUNTIME);
    }
    let mut output = add_retry_runtime(output);
    output = output.replace("\t\"reflect\"\n", "\t\"reflect\"\n\t\"sort\"\n");
    output.push_str(include_str!("../templates/openapi32.go.tmpl"));
    output = output
        .replace(
            "HTTPClient   *http.Client",
            "HTTPClient   PoolsterHTTPClient",
        )
        .replace(
            "httpClient   *http.Client",
            "httpClient   PoolsterHTTPClient",
        );
    output = output.replace("HTTPClient   PoolsterHTTPClient\n", "HTTPClient   PoolsterHTTPClient\n\t// Middleware wraps each transport attempt; first configured is outermost.\n\tMiddleware []PoolsterMiddleware\n");
    output = output.replace("client := &Client{baseURL:", "for index := len(config.Middleware) - 1; index >= 0; index-- {\n\t\tif config.Middleware[index] == nil { return nil, fmt.Errorf(\"poolster: nil middleware\") }\n\t\thttpClient = config.Middleware[index](httpClient)\n\t\tif httpClient == nil { return nil, fmt.Errorf(\"poolster: middleware returned nil transport\") }\n\t}\n\tclient := &Client{baseURL:");
    output = output.replace("Middleware []PoolsterMiddleware\n", "Middleware []PoolsterMiddleware\n\t// ValidateResponses checks named model shapes in buffered JSON responses.\n\tValidateResponses bool\n");
    output = output.replace(
        "hooks        PoolsterClientHooks\n",
        "hooks        PoolsterClientHooks\n\tvalidateResponses bool\n",
    );
    output = output.replace(
        "hooks: config.Hooks}",
        "hooks: config.Hooks, validateResponses: config.ValidateResponses}",
    );
    if api.operations.iter().any(|operation| {
        operation
            .annotations
            .contains_key("x-poolster-idempotency-resolved")
            || operation
                .annotations
                .contains_key("x-kaji-idempotency-resolved")
    }) {
        output = output.replace("\t\"context\"\n", "\t\"context\"\n\t\"crypto/rand\"\n");
        output = output.replace("return strings.TrimSpace(request.Header.Get(\"Idempotency-Key\")) != \"\"", "header, _ := request.Context().Value(poolsterIdempotencyContextKey{}).(string)\n\t\treturn strings.TrimSpace(request.Header.Get(\"Idempotency-Key\")) != \"\" || (header != \"\" && strings.TrimSpace(request.Header.Get(header)) != \"\")");
        output.push_str(include_str!("../templates/idempotency.go.tmpl"));
    }
    output.push_str(&response_validation::render(api));
    output.push_str(include_str!("../templates/middleware.go.tmpl"));
    output = output.replace(
        "\treturn request, nil\n}",
        "\tapplyCallHeaders(request)\n\treturn request, nil\n}",
    );
    output.push_str(include_str!("../templates/call_options.go.tmpl"));
    output = output.replace(
        "\tvar reader io.Reader\n",
        "\tvar reader io.Reader\n\tcontentType := \"application/json\"\n",
    );
    output = output.replace(
        "encoded, err := json.Marshal(body)",
        "encoded, selectedType, err := encodePoolsterWireBody(body)",
    );
    output = output.replace(
        "reader = bytes.NewReader(encoded)",
        "reader = bytes.NewReader(encoded)\n\t\tcontentType = selectedType",
    );
    output = output.replace(
        "request.Header.Set(\"Content-Type\", \"application/json\")",
        "request.Header.Set(\"Content-Type\", contentType)",
    );
    if api.operations.iter().any(has_multipart) {
        output.push_str(include_str!("../templates/multipart.go.tmpl"));
    }
    output.push_str("\nfunc encodePoolsterWireBody(body any) ([]byte,string,error) { if sequential,ok:=body.(poolsterSequentialBody);ok {return encodePoolsterSequential(sequential)}\n");
    if api.operations.iter().any(has_multipart) {
        output.push_str("return encodePoolsterBody(body)\n}\n");
    } else {
        output.push_str(
            "encoded,err:=json.Marshal(body);return encoded,\"application/json\",err\n}\n",
        );
    }
    output = output.replace("ValidateResponses bool\n", "ValidateResponses bool\n\t// TokenProvider supplies managed bearer tokens; explicit Authorization wins.\n\tTokenProvider PoolsterTokenProvider\n");
    output = output.replace(
        "validateResponses bool\n",
        "validateResponses bool\n\ttokenProvider PoolsterTokenProvider\n",
    );
    output = output.replace(
        "validateResponses: config.ValidateResponses}",
        "validateResponses: config.ValidateResponses, tokenProvider: config.TokenProvider}",
    );
    output.push_str("\n// PoolsterTokenProvider supplies a token, refreshing only a rejected cached token.\ntype PoolsterTokenProvider interface { Token(context.Context, string) (string, error) }\n");
    output.push_str("\n// PoolsterHTTPClient is the replaceable execution boundary; context cancellation remains on the request.\ntype PoolsterHTTPClient interface { Do(*http.Request) (*http.Response, error) }\n");
    output
}

fn add_retry_runtime(mut output: String) -> String {
    let needs_errors = output.contains("errors.As(")
        || include_str!("../templates/response_validation.go.tmpl").contains("errors.Is(");
    output = output.replace(
        "\t\"strings\"\n)",
        if needs_errors {
            "\t\"errors\"\n\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)"
        } else {
            "\t\"strconv\"\n\t\"strings\"\n\t\"time\"\n)"
        },
    );
    output = output.replace(
        "\tBody       string\n",
        "\tBody        []byte\n\tContentType string\n",
    );
    output = output.replace(
        "errorResponse.StatusCode, errorResponse.Body)",
        "errorResponse.StatusCode, string(errorResponse.Body))",
    );
    output = output.replace(
        "Body: string(body)",
        "Body: body, ContentType: response.Header.Get(\"Content-Type\")",
    );
    output = output.replace(
        "\tHTTPClient   *http.Client\n}",
        "\tHTTPClient   *http.Client\n\t// Retry configures safe automatic retries. Nil uses Poolster defaults; set\n\t// MaxAttempts to 1 to disable retries.\n\tRetry        *RetryConfig\n\t// Hooks observes the final lifecycle of a logical request. It receives no\n\t// request headers or bodies, so credentials stay private by default.\n\tHooks        PoolsterClientHooks\n}",
    );
    output = output.replace(
        "\thttpClient   *http.Client\n",
        "\thttpClient   *http.Client\n\tretry        retryConfig\n\thooks        PoolsterClientHooks\n",
    );
    output = output.replace(
        "client := &Client{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient}",
        "client := &Client{baseURL: baseURL, apiKey: config.APIKey, apiKeyHeader: header, apiKeyPrefix: config.APIKeyPrefix, httpClient: httpClient, retry: normalizeRetry(config.Retry), hooks: config.Hooks}",
    );
    output = output.replace("client.do(request,", "client.doWithRetry(request,");
    output.push_str(include_str!("../templates/retry.go.tmpl"));
    output
}

#[derive(Clone, Debug)]
enum GoResponseKind {
    None,
    Json(String),
    Text,
    Binary,
    EventStream,
}

const PAGINATION_RUNTIME: &str = include_str!("../templates/pagination.go.tmpl");

#[derive(Clone, Debug)]
enum GoCursorLocation {
    Parameter {
        name: String,
        optional: bool,
    },
    /// Request-body cursor pagers are deliberately limited to a named object
    /// schema with an optional string field. That lets us clone and update a
    /// typed request without mutating the caller's value or guessing JSON.
    RequestBody {
        body_type: String,
        field_name: String,
        body_required: bool,
    },
}

#[derive(Clone, Debug)]
struct GoCursorPagination {
    location: GoCursorLocation,
    next_cursor_path: String,
}

#[derive(Clone, Debug)]
struct GoUrlPagination {
    next_url_path: String,
}

#[derive(Clone, Debug)]
struct GoOffsetPagination {
    offset_name: String,
    limit_name: String,
    results_path: String,
}

fn offset_pagination(api: &Api, operation: &Operation) -> Option<GoOffsetPagination> {
    // Legacy offset rendering accepts opaque response envelopes.
    let mut declaration = operation.clone();
    declaration.responses.clear();
    let plan = poolster_core::pagination::normalize_pagination(api, &declaration, None)
        .ok()
        .flatten()?;
    if plan.kind != poolster_core::pagination::PaginationKind::OffsetLimit {
        return None;
    }
    let find = |role: &str| {
        let input = plan.inputs.iter().find(|input| {
            input.role == role && input.location != "requestBody" && !input.required
        })?;
        let parameter = operation
            .parameters
            .iter()
            .find(|parameter| parameter.name == input.name)?;
        Some(parameter_field_name(operation, parameter))
    };
    Some(GoOffsetPagination {
        offset_name: find("offset")?,
        limit_name: find("limit")?,
        results_path: native_selector(&plan.results?)?,
    })
}

fn cursor_pagination(api: &Api, operation: &Operation) -> Option<GoCursorPagination> {
    let plan = poolster_core::pagination::normalize_pagination(api, operation, None)
        .ok()
        .flatten()?;
    if plan.kind != poolster_core::pagination::PaginationKind::Cursor {
        return None;
    }
    let input = plan.inputs.iter().find(|input| input.role == "cursor")?;
    if input.value_kind != poolster_core::pagination::PaginationValueKind::String {
        return None;
    }
    let cursor_name = input.name.as_str();
    let next_cursor_path = native_selector(&plan.continuation?)?;
    let location = if input.location == "requestBody" {
        body_cursor_location(api, operation, cursor_name)?
    } else {
        let parameter = operation.parameters.iter().find(|parameter| {
            parameter.name == cursor_name
                && matches!(parameter.location.as_str(), "query" | "header" | "path")
                && matches!(
                    parameter.schema.as_ref().map(|schema| &schema.kind),
                    Some(SchemaKind::String)
                )
        })?;
        // OpenAPI path parameters are always required. Do not turn an invalid
        // optional path parameter into a paginator API.
        if parameter.location == "path" && !parameter.required {
            return None;
        }
        GoCursorLocation::Parameter {
            name: parameter_field_name(operation, parameter),
            optional: !parameter.required,
        }
    };
    Some(GoCursorPagination {
        location,
        next_cursor_path,
    })
}

fn native_selector(selector: &poolster_core::pagination::Selector) -> Option<String> {
    use poolster_core::pagination::SelectorSegment;
    if selector.expression.starts_with('/') {
        return Some(selector.expression.clone());
    }
    let mut output = String::from("$");
    for segment in &selector.segments {
        match segment {
            SelectorSegment::Field(name) if !name.contains(['.', '[', ']']) => {
                output.push('.');
                output.push_str(name);
            }
            SelectorSegment::Index(index) => output.push_str(&format!("[{index}]")),
            _ => return None,
        }
    }
    Some(output)
}

fn body_cursor_location(
    api: &Api,
    operation: &Operation,
    cursor_name: &str,
) -> Option<GoCursorLocation> {
    let body = operation.request_body.as_ref()?;
    let schema = body
        .media_types
        .iter()
        .find(|media| media.content_type.contains("json"))
        .or_else(|| body.media_types.first())?
        .schema
        .as_ref()?;
    let SchemaKind::Reference { reference } = &schema.kind else {
        return None;
    };
    let body_name = reference.rsplit('/').next()?;
    let body_schema = api.schemas.iter().find(|schema| schema.name == body_name)?;
    let SchemaKind::Object { fields, .. } = &body_schema.value.kind else {
        return None;
    };
    let field = fields.iter().find(|field| {
        field.name == cursor_name
            && !field.required
            && matches!(field.value.kind, SchemaKind::String)
    })?;
    Some(GoCursorLocation::RequestBody {
        body_type: go_type_name(body_name),
        field_name: model_field_names(fields)[&field.name].clone(),
        body_required: body.required,
    })
}

fn url_pagination(api: &Api, operation: &Operation) -> Option<GoUrlPagination> {
    let plan = poolster_core::pagination::normalize_pagination(api, operation, None)
        .ok()
        .flatten()?;
    if plan.kind != poolster_core::pagination::PaginationKind::Url {
        return None;
    }
    Some(GoUrlPagination {
        next_url_path: native_selector(&plan.continuation?)?,
    })
}

fn sequential_media(content_type: &str) -> bool {
    let media = content_type
        .split(';')
        .next()
        .unwrap_or_default()
        .trim()
        .to_ascii_lowercase();
    matches!(
        media.as_str(),
        "application/x-ndjson"
            | "application/ndjson"
            | "application/jsonl"
            | "application/json-seq"
    ) || media.ends_with("+json-seq")
}

fn operation_response_kind(operation: &Operation) -> GoResponseKind {
    let media = operation
        .responses
        .iter()
        .find(|response| response.status.starts_with('2'))
        .or_else(|| {
            operation
                .responses
                .iter()
                .find(|response| response.status == "default")
        })
        .and_then(|response| response.media_types.first());
    let Some(media) = media else {
        return operation_response_type(operation)
            .map(GoResponseKind::Json)
            .unwrap_or(GoResponseKind::None);
    };
    let content_type = media.content_type.to_ascii_lowercase();
    if content_type.starts_with("multipart/") {
        return GoResponseKind::Binary;
    }
    if content_type.starts_with("text/event-stream") {
        return GoResponseKind::EventStream;
    }
    if content_type.contains("json") {
        return GoResponseKind::Json(
            media
                .schema
                .as_ref()
                .map(go_type)
                .or_else(|| operation_response_type(operation))
                .unwrap_or_else(|| "any".into()),
        );
    }
    if content_type.starts_with("text/") {
        return GoResponseKind::Text;
    }
    if content_type.starts_with("application/octet-stream")
        || media.schema.as_ref().is_some_and(|schema| {
            matches!(&schema.kind, SchemaKind::String)
                && matches!(schema.format.as_deref(), Some("binary") | Some("byte"))
        })
    {
        return GoResponseKind::Binary;
    }
    media
        .schema
        .as_ref()
        .map(go_type)
        .map(GoResponseKind::Json)
        .unwrap_or(GoResponseKind::None)
}

fn error_responses(
    operation: &Operation,
) -> impl Iterator<Item = &poolster_core::OperationResponse> {
    operation.responses.iter().filter(|response| {
        response.status == "default"
            || response
                .status
                .parse::<u16>()
                .is_ok_and(|status| (400..600).contains(&status))
    })
}

fn declared_error_name(operation: &Operation, status: &str) -> String {
    let suffix = if status == "default" {
        "Default".to_owned()
    } else {
        status.to_owned()
    };
    format!("{}Error{suffix}", go_type_name(&operation.id))
}

fn render_declared_errors(output: &mut String, operation: &Operation) {
    for response in error_responses(operation) {
        let name = declared_error_name(operation, &response.status);
        let media = response.media_types.first();
        let body_type = media.and_then(|media| media.schema.as_ref()).map(go_type);
        let _ = writeln!(
            output,
            "// {name} is returned when {} responds with status {}.",
            go_type_name(&operation.id),
            response.status
        );
        let _ = writeln!(output, "type {name} struct {{");
        output.push_str("\tStatusCode int\n\tRawBody    []byte\n");
        if let Some(body_type) = &body_type {
            let _ = writeln!(output, "\tBody       {body_type}");
        }
        output.push_str("}\n\n");
        let _ = writeln!(output, "func (errorResponse *{name}) Error() string {{");
        let _ = writeln!(
            output,
            "\treturn fmt.Sprintf(\"poolster: {} failed with status %d\", errorResponse.StatusCode)",
            go_type_name(&operation.id)
        );
        output.push_str("}\n\n");
    }
    if error_responses(operation).next().is_none() {
        return;
    }
    let decoder = format!("decode{}Error", go_type_name(&operation.id));
    let _ = writeln!(output, "func {decoder}(requestError error) error {{");
    output.push_str("\tvar transportError *poolsterAPIError\n\tif !errors.As(requestError, &transportError) { return requestError }\n\tswitch transportError.StatusCode {\n");
    for response in error_responses(operation) {
        if response.status == "default" {
            continue;
        }
        let name = declared_error_name(operation, &response.status);
        let _ = writeln!(output, "\tcase {}:", response.status);
        let _ = writeln!(
            output,
            "\t\tresult := &{name}{{StatusCode: transportError.StatusCode, RawBody: transportError.Body}}"
        );
        render_error_body_decode(output, response, "result");
        output.push_str("\t\treturn result\n");
    }
    if let Some(default_response) =
        error_responses(operation).find(|response| response.status == "default")
    {
        let name = declared_error_name(operation, "default");
        output.push_str("\tdefault:\n");
        let _ = writeln!(
            output,
            "\t\tresult := &{name}{{StatusCode: transportError.StatusCode, RawBody: transportError.Body}}"
        );
        render_error_body_decode(output, default_response, "result");
        output.push_str("\t\treturn result\n");
    } else {
        output.push_str("\tdefault:\n\t\treturn requestError\n");
    }
    output.push_str("\t}\n}\n\n");
}

fn render_error_body_decode(
    output: &mut String,
    response: &poolster_core::OperationResponse,
    target: &str,
) {
    let Some(schema) = response
        .media_types
        .first()
        .and_then(|media| media.schema.as_ref())
    else {
        return;
    };
    let content_type = response
        .media_types
        .first()
        .map(|media| media.content_type.as_str())
        .unwrap_or_default();
    if content_type.contains("json") {
        let _ = writeln!(
            output,
            "\t\tif len(transportError.Body) > 0 {{ _ = json.Unmarshal(transportError.Body, &{target}.Body) }}"
        );
    } else if content_type.starts_with("text/") && matches!(&schema.kind, SchemaKind::String) {
        let _ = writeln!(output, "\t\t{target}.Body = string(transportError.Body)");
    } else if matches!(&schema.kind, SchemaKind::String)
        && matches!(schema.format.as_deref(), Some("binary") | Some("byte"))
    {
        let _ = writeln!(
            output,
            "\t\t{target}.Body = append([]byte(nil), transportError.Body...)"
        );
    }
}

fn operation_error_expression(operation: &Operation, error: &str) -> String {
    if error_responses(operation).next().is_some() {
        format!("decode{}Error({error})", go_type_name(&operation.id))
    } else {
        error.to_owned()
    }
}

/// Allocate operation input types separately from schema types. Reserve every
/// preferred input name first so adding a collision never steals another
/// operation's existing public name.
fn operation_request_name(api: &Api, operation: &Operation) -> String {
    let preferred = format!("{}Request", go_type_name(&operation.id));
    let mut reserved: BTreeSet<String> = api
        .schemas
        .iter()
        .map(|schema| go_type_name(&schema.name))
        .collect();
    if !reserved.contains(&preferred) {
        return preferred;
    }
    reserved.extend(
        api.operations
            .iter()
            .map(|op| format!("{}Request", go_type_name(&op.id))),
    );
    let model_names: BTreeSet<String> = api
        .schemas
        .iter()
        .map(|schema| go_type_name(&schema.name))
        .collect();
    let mut collisions = api
        .operations
        .iter()
        .filter(|op| model_names.contains(&format!("{}Request", go_type_name(&op.id))))
        .collect::<Vec<_>>();
    collisions.sort_by(|a, b| a.id.cmp(&b.id));
    for op in collisions {
        let base = format!("{}OperationRequest", go_type_name(&op.id));
        let mut name = base.clone();
        let mut suffix = 2;
        while !reserved.insert(name.clone()) {
            name = format!("{base}{suffix}");
            suffix += 1;
        }
        if op.id == operation.id {
            return name;
        }
    }
    unreachable!("colliding operation belongs to API")
}

fn render_operation(output: &mut String, api: &Api, operation: &Operation) {
    let operation_name = go_type_name(&operation.id);
    let request_name = operation_request_name(api, operation);
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    if has_input {
        let _ = writeln!(
            output,
            "// {request_name} contains the inputs for {operation_name}."
        );
        let _ = writeln!(output, "type {request_name} struct {{");
        for parameter in &operation.parameters {
            render_parameter_field(
                output,
                parameter,
                &parameter_field_name(operation, parameter),
            );
        }
        if let Some(body) = &operation.request_body {
            let body_type = body
                .media_types
                .iter()
                .find(|media_type| media_type.content_type.contains("json"))
                .or_else(|| body.media_types.first())
                .and_then(|media_type| media_type.schema.as_ref())
                .map(go_type)
                .unwrap_or_else(|| "any".into());
            let body_type = if has_multipart(operation) {
                if body
                    .media_types
                    .iter()
                    .any(|media| media.content_type.contains("json"))
                {
                    "any".to_owned()
                } else {
                    "*PoolsterMultipartBody".to_owned()
                }
            } else if body.required || body_type.starts_with('*') {
                body_type
            } else {
                format!("*{body_type}")
            };
            let _ = writeln!(output, "\tBody {body_type} `json:\"body,omitempty\"`");
        }
        output.push_str("}\n\n");
    }

    render_declared_errors(output, operation);
    let response_kind = operation_response_kind(operation);
    let parameters = if has_input {
        format!(", input *{request_name}")
    } else {
        String::new()
    };
    let result = match &response_kind {
        GoResponseKind::None => "error".to_owned(),
        GoResponseKind::Json(response) => format!("(*{response}, error)"),
        GoResponseKind::Text => "(string, error)".to_owned(),
        GoResponseKind::Binary => "([]byte, error)".to_owned(),
        GoResponseKind::EventStream => "(io.ReadCloser, error)".to_owned(),
    };
    let _ = writeln!(
        output,
        "// {operation_name} invokes {} {}.\nfunc (client *Client) {operation_name}(ctx context.Context{parameters}) {result} {{",
        operation.method.as_str(),
        operation.path
    );
    if has_input {
        output.push_str("\tif input == nil {\n\t\tinput = &");
        output.push_str(&request_name);
        output.push_str("{}\n\t}\n");
    }
    let _ = writeln!(output, "\tpath := {:?}", operation.path);
    output.push_str("\tquery := url.Values{}\n\theaders := http.Header{}\n");
    if operation
        .parameters
        .iter()
        .any(|p| p.location == "querystring")
    {
        output.push_str("\tvar wholeQuery string\n");
    }
    for parameter in &operation.parameters {
        render_parameter_use(
            output,
            parameter,
            &parameter_field_name(operation, parameter),
            &response_kind,
        );
    }
    let idempotency = operation
        .annotations
        .get("x-poolster-idempotency-resolved")
        .or_else(|| operation.annotations.get("x-kaji-idempotency-resolved"));
    if let Some(rule) = idempotency {
        if rule
            .get("auto_generate")
            .and_then(serde_json::Value::as_bool)
            == Some(true)
        {
            let header = rule
                .get("header")
                .and_then(serde_json::Value::as_str)
                .unwrap();
            let _ = writeln!(
                output,
                "\tif len(headers.Values({header:?})) == 0 {{\n\t\tkey, err := poolsterNewIdempotencyKey()\n\t\tif err != nil {{"
            );
            render_error_return(
                output,
                &response_kind,
                &operation_error_expression(operation, "err"),
            );
            let _ = writeln!(output, "\t\t}}\n\t\theaders.Set({header:?}, key)\n\t}}");
        }
    }
    if let Some(body_config) = &operation.request_body {
        if has_multipart(operation) && !body_config.required {
            output.push_str("\tvar body any\n\tif input.Body != nil { body = input.Body }\n");
        } else {
            if body_config
                .media_types
                .first()
                .is_some_and(|media| sequential_media(&media.content_type))
            {
                output.push_str("\tvar body any = input.Body\n");
            } else {
                output.push_str("\tbody := input.Body\n");
            }
        }
    } else {
        output.push_str("\tvar body any\n");
    }
    if has_multipart(operation) {
        let media = operation
            .request_body
            .as_ref()
            .unwrap()
            .media_types
            .iter()
            .find(|m| {
                m.content_type
                    .to_ascii_lowercase()
                    .starts_with("multipart/")
            })
            .unwrap();
        let metadata = poolster_core::openapi32::request_content(operation)
            .expect("validated content metadata")
            .into_iter()
            .find(|m| m.content_type == media.content_type)
            .unwrap_or_else(|| poolster_core::openapi32::ContentDefinition {
                content_type: media.content_type.clone(),
                ..Default::default()
            });
        let encoded = serde_json::to_string(&metadata).expect("typed multipart metadata");
        let _ = writeln!(
            output,
            "\tif multipartBody, ok := any(body).(*PoolsterMultipartBody); ok && multipartBody != nil {{\n\t\tpreparedMultipart, preparationError := poolsterDeclaredMultipart(multipartBody, {:?})\n\t\tif preparationError != nil {{",
            encoded
        );
        render_error_return(output, &response_kind, "preparationError");
        output.push_str("\t\t}\n\t\tbody = preparedMultipart\n\t}\n");
    }
    if let Some(media) = operation
        .request_body
        .as_ref()
        .and_then(|b| b.media_types.first())
    {
        if sequential_media(&media.content_type) {
            let _ = writeln!(
                output,
                "\tif body != nil {{ body = poolsterSequentialBody{{ContentType:{:?},Value:body}} }}",
                media.content_type
            );
        }
    }
    let _ = writeln!(
        output,
        "\trequest, err := client.newRequest(ctx, {:?}, path, query, headers, body)",
        operation.method.as_str()
    );
    output.push_str("\tif err != nil {\n");
    render_error_return(
        output,
        &response_kind,
        &operation_error_expression(operation, "err"),
    );
    output.push_str("\t}\n");
    if operation
        .parameters
        .iter()
        .any(|p| p.location == "querystring")
    {
        output.push_str("\trequest.URL.RawQuery = wholeQuery\n");
    }
    if let Some(header) = idempotency
        .and_then(|rule| rule.get("header"))
        .and_then(serde_json::Value::as_str)
    {
        let _ = writeln!(
            output,
            "\trequest = request.WithContext(context.WithValue(request.Context(), poolsterIdempotencyContextKey{{}}, {header:?}))"
        );
    }
    match response_kind {
        GoResponseKind::None => {
            output.push_str("\tif err := client.do(request, nil); err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::None,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn nil\n}\n\n");
        }
        GoResponseKind::Json(response) => {
            let _ = writeln!(output, "\tvar response {response}");
            output.push_str("\tif err := client.do(request, &response); err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::Json(response.clone()),
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn &response, nil\n}\n\n");
        }
        GoResponseKind::Text => {
            output.push_str(
                "\tvar response string\n\tif err := client.do(request, &response); err != nil {\n",
            );
            render_error_return(
                output,
                &GoResponseKind::Text,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
        GoResponseKind::Binary => {
            output.push_str(
                "\tvar response []byte\n\tif err := client.do(request, &response); err != nil {\n",
            );
            render_error_return(
                output,
                &GoResponseKind::Binary,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
        GoResponseKind::EventStream => {
            output.push_str("\tresponse, err := client.stream(request)\n\tif err != nil {\n");
            render_error_return(
                output,
                &GoResponseKind::EventStream,
                &operation_error_expression(operation, "err"),
            );
            output.push_str("\t}\n\treturn response, nil\n}\n\n");
        }
    }
}

fn render_cursor_pager(output: &mut String, api: &Api, operation: &Operation) {
    let Some(pagination) = cursor_pagination(api, operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = operation_request_name(api, operation);
    let pager_name = format!("{operation_name}Pager");
    let cursor_update = match &pagination.location {
        GoCursorLocation::Parameter { name, optional } => {
            let field = name;
            if *optional {
                format!("\tif pager.started {{ pager.input.{field} = &pager.cursor }}\n")
            } else {
                format!("\tif pager.started {{ pager.input.{field} = pager.cursor }}\n")
            }
        }
        GoCursorLocation::RequestBody {
            body_type,
            field_name,
            body_required,
        } => {
            if *body_required {
                format!(
                    "\tif pager.started {{\n\t\tbodyCopy := pager.input.Body\n\t\tbodyCopy.{field_name} = &pager.cursor\n\t\tpager.input.Body = bodyCopy\n\t}}\n"
                )
            } else {
                format!(
                    "\tif pager.started {{\n\t\tif pager.input.Body == nil {{ return nil, fmt.Errorf(\"poolster: cursor pagination requires a {body_type} body\") }}\n\t\tbodyCopy := *pager.input.Body\n\t\tbodyCopy.{field_name} = &pager.cursor\n\t\tpager.input.Body = &bodyCopy\n\t}}\n"
                )
            }
        }
    };
    let body_preflight = match &pagination.location {
        GoCursorLocation::RequestBody {
            body_type,
            body_required: false,
            ..
        } => format!(
            "\tif pager.input.Body == nil {{ return nil, fmt.Errorf(\"poolster: cursor pagination requires a {body_type} body\") }}\n"
        ),
        _ => String::new(),
    };
    let _ = writeln!(
        output,
        "// {pager_name} iterates pages returned by {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n\tinput *{request_name}\n\tcursor string\n\tstarted bool\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts cursor pagination without guessing fields from a response."
    );
    let _ = writeln!(
        output,
        "func (client *Client) {operation_name}Pages(input *{request_name}) *{pager_name} {{"
    );
    let _ = writeln!(output, "\tcopyInput := &{request_name}{{}}");
    output.push_str("\tif input != nil { *copyInput = *input }\n");
    let _ = writeln!(
        output,
        "\treturn &{pager_name}{{client: client, input: copyInput}}\n}}"
    );
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page."
    );
    let _ = writeln!(
        output,
        "func (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    output.push_str(&body_preflight);
    output.push_str(&cursor_update);
    let _ = writeln!(
        output,
        "\tresponse, err := pager.client.{operation_name}(ctx, pager.input)"
    );
    output.push_str("\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\tcursor, ok := poolsterPaginationString(response, {:?})",
        pagination.next_cursor_path
    );
    output.push_str("\tif !ok { pager.done = true; return response, nil }\n\tpager.cursor = cursor\n\tpager.started = true\n\treturn response, nil\n}\n\n");
}

fn render_offset_pager(output: &mut String, api: &Api, operation: &Operation) {
    let Some(pagination) = offset_pagination(api, operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = operation_request_name(api, operation);
    let pager_name = format!("{operation_name}Pager");
    let offset_field = &pagination.offset_name;
    let limit_field = &pagination.limit_name;
    let _ = writeln!(
        output,
        "// {pager_name} iterates declared offset/limit pages returned by {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n\tinput *{request_name}\n\toffset int64\n\tlimit *int64\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts declared offset/limit pagination."
    );
    let _ = writeln!(
        output,
        "func (client *Client) {operation_name}Pages(input *{request_name}) *{pager_name} {{"
    );
    let _ = writeln!(output, "\tcopyInput := &{request_name}{{}}");
    output.push_str("\tif input != nil { *copyInput = *input }\n");
    let _ = writeln!(output, "\toffset := int64(0)");
    let _ = writeln!(
        output,
        "\tif copyInput.{offset_field} != nil {{ offset = *copyInput.{offset_field} }}"
    );
    let _ = writeln!(
        output,
        "\treturn &{pager_name}{{client: client, input: copyInput, offset: offset, limit: copyInput.{limit_field}}}\n}}"
    );
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page."
    );
    let _ = writeln!(
        output,
        "func (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    let _ = writeln!(output, "\tpager.input.{offset_field} = &pager.offset");
    let _ = writeln!(
        output,
        "\tresponse, err := pager.client.{operation_name}(ctx, pager.input)"
    );
    output.push_str("\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\tcount, ok := poolsterPaginationArrayLen(response, {:?})",
        pagination.results_path
    );
    output.push_str("\tif !ok || count == 0 { pager.done = true; return response, nil }\n");
    output.push_str("\tpager.offset += int64(count)\n");
    output
        .push_str("\tif pager.limit != nil && int64(count) < *pager.limit { pager.done = true }\n");
    output.push_str("\treturn response, nil\n}\n\n");
}

fn render_url_pager(output: &mut String, api: &Api, operation: &Operation) {
    let Some(pagination) = url_pagination(api, operation) else {
        return;
    };
    let GoResponseKind::Json(response_type) = operation_response_kind(operation) else {
        return;
    };
    let operation_name = go_type_name(&operation.id);
    let request_name = operation_request_name(api, operation);
    let pager_name = format!("{operation_name}Pager");
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    let input_field = if has_input {
        format!("\tinput *{request_name}\n")
    } else {
        String::new()
    };
    let constructor_input = if has_input {
        format!("input *{request_name}")
    } else {
        String::new()
    };
    let constructor_copy = if has_input {
        format!(
            "\tcopyInput := &{request_name}{{}}\n\tif input != nil {{ *copyInput = *input }}\n\treturn &{pager_name}{{client: client, input: copyInput}}\n"
        )
    } else {
        format!("\treturn &{pager_name}{{client: client}}\n")
    };
    let initial_call = if has_input {
        format!("pager.client.{operation_name}(ctx, pager.input)")
    } else {
        format!("pager.client.{operation_name}(ctx)")
    };
    let mut continuation_prep = String::from("\theaders := http.Header{}\n");
    if has_input {
        render_pagination_headers(&mut continuation_prep, operation);
    }
    if has_input && operation.request_body.is_some() {
        continuation_prep.push_str("\tbody := pager.input.Body\n");
    } else {
        continuation_prep.push_str("\tvar body any\n");
    }
    let error_expression = operation_error_expression(operation, "err");
    let _ = writeln!(
        output,
        "// {pager_name} follows declared same-origin continuation URLs for {operation_name}."
    );
    let _ = writeln!(output, "type {pager_name} struct {{");
    let _ = writeln!(
        output,
        "\tclient *Client\n{input_field}\tnextURL string\n\tstarted bool\n\tdone bool\n}}"
    );
    let _ = writeln!(
        output,
        "// {operation_name}Pages starts URL pagination using the operation's normal typed request.\nfunc (client *Client) {operation_name}Pages({constructor_input}) *{pager_name} {{"
    );
    output.push_str(&constructor_copy);
    output.push_str("}\n");
    let _ = writeln!(
        output,
        "// Next returns the next full response page, or io.EOF after the final page.\nfunc (pager *{pager_name}) Next(ctx context.Context) (*{response_type}, error) {{"
    );
    output.push_str("\tif pager.done { return nil, io.EOF }\n");
    output.push_str("\tif !pager.started {\n");
    let _ = writeln!(output, "\t\tresponse, err := {initial_call}");
    output.push_str("\t\tif err != nil { return nil, err }\n");
    let _ = writeln!(
        output,
        "\t\tnextURL, ok := poolsterPaginationString(response, {:?})",
        pagination.next_url_path
    );
    output.push_str("\t\tpager.started = true\n\t\tif !ok { pager.done = true; return response, nil }\n\t\tpager.nextURL = nextURL\n\t\treturn response, nil\n\t}\n");
    output.push_str(&continuation_prep);
    let _ = writeln!(
        output,
        "\trequest, err := pager.client.newPaginationRequest(ctx, {:?}, pager.nextURL, headers, body)",
        operation.method.as_str()
    );
    let _ = writeln!(
        output,
        "\tif err != nil {{ return nil, {error_expression} }}"
    );
    let _ = writeln!(output, "\tvar response {response_type}");
    let _ = writeln!(
        output,
        "\tif err := pager.client.doWithRetry(request, &response); err != nil {{ return nil, {error_expression} }}"
    );
    let _ = writeln!(
        output,
        "\tnextURL, ok := poolsterPaginationString(&response, {:?})",
        pagination.next_url_path
    );
    output.push_str("\tif !ok { pager.done = true } else { pager.nextURL = nextURL }\n\treturn &response, nil\n}\n\n");
}

fn render_pagination_headers(output: &mut String, operation: &Operation) {
    for parameter in &operation.parameters {
        if parameter.location != "header" {
            continue;
        }
        let field = format!("pager.input.{}", parameter_field_name(operation, parameter));
        if parameter.required {
            let _ = writeln!(
                output,
                "\theaders.Set({:?}, fmt.Sprint({field}))",
                parameter.name
            );
        } else {
            let _ = writeln!(
                output,
                "\tif {field} != nil {{ headers.Set({:?}, fmt.Sprint(*{field})) }}",
                parameter.name
            );
        }
    }
}

fn parameter_field_name(operation: &Operation, parameter: &OperationParameter) -> String {
    let preferred: Vec<_> = operation
        .parameters
        .iter()
        .map(|parameter| go_type_name(&parameter.name))
        .collect();
    let mut reserved: BTreeSet<_> = preferred.iter().cloned().collect();
    let mut used = BTreeSet::new();
    if operation.request_body.is_some() {
        reserved.insert("Body".into());
        used.insert("Body".into());
    }
    for (index, candidate) in operation.parameters.iter().enumerate() {
        let base = &preferred[index];
        let collision =
            preferred.iter().filter(|name| *name == base).count() > 1 || used.contains(base);
        let mut name = if collision {
            format!("{}{base}", go_type_name(&candidate.location))
        } else {
            base.clone()
        };
        let seed = name.clone();
        let mut suffix = 2;
        while used.contains(&name) || (name != *base && reserved.contains(&name)) {
            name = format!("{seed}{suffix}");
            suffix += 1;
        }
        used.insert(name.clone());
        if std::ptr::eq(candidate, parameter) {
            return name;
        }
    }
    unreachable!("parameter belongs to the operation")
}

fn render_parameter_field(output: &mut String, parameter: &OperationParameter, name: &str) {
    let mut value_type = parameter
        .schema
        .as_ref()
        .map(go_type)
        .unwrap_or_else(|| "any".into());
    if !parameter.required && parameter.location != "path" && !value_type.starts_with('*') {
        value_type = format!("*{value_type}");
    }
    let _ = writeln!(
        output,
        "\t{name} {value_type} `json:\"{},omitempty\"`",
        parameter.name
    );
}

fn render_parameter_use(
    output: &mut String,
    parameter: &OperationParameter,
    name: &str,
    response_kind: &GoResponseKind,
) {
    let field = format!("input.{name}");
    if parameter.location != "querystring" {
        if let Some(content) = poolster_core::openapi32::parameter_content(parameter)
            .expect("validated parameter content")
            .first()
        {
            let value = format!("poolsterContent{name}");
            let present = format!("poolsterPresent{name}");
            let error = format!("poolsterError{name}");
            let _ = writeln!(
                output,
                "\t{value}, {present}, {error} := poolsterParameterContent({field}, {:?})\n\tif {error} != nil {{",
                content.content_type
            );
            render_error_return(output, response_kind, &error);
            output.push_str("\t}\n");
            let _ = writeln!(output, "\tif {present} {{");
            match parameter.location.as_str() {
                "query" => {
                    let _ = writeln!(output, "\t\tquery.Add({:?}, {value})", parameter.name);
                }
                "path" => {
                    let _ = writeln!(
                        output,
                        "\t\tpath = strings.ReplaceAll(path, {:?}, url.PathEscape({value}))",
                        format!("{{{}}}", parameter.name)
                    );
                }
                "header" => {
                    let _ = writeln!(output, "\t\theaders.Set({:?}, {value})", parameter.name);
                }
                "cookie" => {
                    let _ = writeln!(
                        output,
                        "\t\theaders.Add(\"Cookie\", {:?} + \"=\" + strings.ReplaceAll(url.QueryEscape({value}), \"+\", \"%20\"))",
                        parameter.name
                    );
                }
                _ => {}
            }
            output.push_str("\t}\n");
            return;
        }
    }
    match parameter.location.as_str() {
        "path" => {
            let _ = writeln!(
                output,
                "\tpath = strings.ReplaceAll(path, {:?}, url.PathEscape(fmt.Sprint({field})))",
                format!("{{{}}}", parameter.name)
            );
        }
        "querystring" => {
            let content = poolster_core::openapi32::parameter_content(parameter)
                .expect("validated content metadata")
                .into_iter()
                .next()
                .unwrap_or_else(|| poolster_core::openapi32::ContentDefinition {
                    content_type: "text/plain".into(),
                    ..Default::default()
                });
            let content_type = content.content_type.clone();
            let metadata = serde_json::to_string(&content).expect("typed content metadata");
            let _ = writeln!(
                output,
                "\tencodedQuery, queryError := poolsterWholeQuery({field}, {content_type:?}, {metadata:?})\n\tif queryError != nil {{"
            );
            render_error_return(output, response_kind, "queryError");
            output.push_str("\t}\n\twholeQuery = encodedQuery\n");
        }
        "query" => {
            let _ = writeln!(
                output,
                "\tif err := addQuery(query, {:?}, {field}); err != nil {{",
                parameter.name
            );
            render_error_return(output, response_kind, "err");
            output.push_str("\t}\n");
        }
        "header" => {
            if parameter.required {
                let _ = writeln!(
                    output,
                    "\theaders.Set({:?}, fmt.Sprint({field}))",
                    parameter.name
                );
            } else {
                let _ = writeln!(
                    output,
                    "\tif {field} != nil {{ headers.Set({:?}, fmt.Sprint(*{field})) }}",
                    parameter.name
                );
            }
        }
        _ => {}
    }
}

fn render_error_return(output: &mut String, response_kind: &GoResponseKind, error: &str) {
    match response_kind {
        GoResponseKind::None => {
            let _ = writeln!(output, "\t\treturn {error}");
        }
        GoResponseKind::Text => {
            let _ = writeln!(output, "\t\treturn \"\", {error}");
        }
        GoResponseKind::Json(_) | GoResponseKind::Binary | GoResponseKind::EventStream => {
            let _ = writeln!(output, "\t\treturn nil, {error}");
        }
    }
}

fn operation_response_type(operation: &Operation) -> Option<String> {
    operation.success_schema().map(go_type)
}

fn go_type(value: &SchemaValue) -> String {
    let value_type = match &value.kind {
        SchemaKind::Any | SchemaKind::Null | SchemaKind::Not { .. } => "any".into(),
        SchemaKind::Boolean => "bool".into(),
        SchemaKind::Integer => "int64".into(),
        SchemaKind::Number => "float64".into(),
        SchemaKind::String => match value.format.as_deref() {
            Some("binary") | Some("byte") => "[]byte".into(),
            _ => "string".into(),
        },
        SchemaKind::Array { items } => format!("[]{}", go_type(items)),
        SchemaKind::Object {
            additional_properties,
            ..
        } => match additional_properties {
            AdditionalProperties::Schema { value } => format!("map[string]{}", go_type(value)),
            _ => "map[string]any".into(),
        },
        SchemaKind::Reference { reference } => go_type_name(
            &reference
                .rsplit('/')
                .next()
                .unwrap_or(reference)
                .replace("~1", "/")
                .replace("~0", "~"),
        ),
        SchemaKind::OneOf { .. } | SchemaKind::AnyOf { .. } | SchemaKind::AllOf { .. } => {
            "json.RawMessage".into()
        }
    };
    if (value.nullable || value.nullish) && value_type != "any" && !value_type.starts_with('*') {
        format!("*{value_type}")
    } else {
        value_type
    }
}

fn resource_operations(api: &Api) -> BTreeMap<String, Vec<&Operation>> {
    let mut resources = BTreeMap::<String, Vec<&Operation>>::new();
    for operation in &api.operations {
        resources
            .entry(go_type_name(&resource_name(operation)))
            .or_default()
            .push(operation);
    }
    resources
}

fn resource_name(operation: &Operation) -> String {
    operation
        .annotations
        .get("tags")
        .and_then(|tags| tags.as_array())
        .and_then(|tags| tags.first())
        .and_then(|tag| tag.as_str())
        .filter(|tag| !tag.trim().is_empty())
        .map(str::to_owned)
        .or_else(|| {
            operation
                .path
                .split('/')
                .filter(|segment| !segment.is_empty() && !segment.starts_with('{'))
                .find(|segment| {
                    !matches!(*segment, "api" | "email") && !is_version_segment(segment)
                })
                .map(str::to_owned)
        })
        .unwrap_or_else(|| "api".into())
}

fn is_version_segment(segment: &str) -> bool {
    let mut characters = segment.chars();
    matches!(characters.next(), Some('v' | 'V'))
        && characters
            .next()
            .is_some_and(|character| character.is_ascii_digit())
}

/// Go selectors share a namespace with methods. A resource whose generated
/// field matches any direct operation therefore receives a stable `Resource`
/// suffix instead of producing an uncompilable client (for example an
/// `auth-check` resource alongside `Client.AuthCheck`).
fn resource_facade_names(
    resources: &BTreeMap<String, Vec<&Operation>>,
) -> BTreeMap<String, String> {
    let operations: BTreeSet<_> = resources
        .values()
        .flatten()
        .map(|operation| go_type_name(&operation.id))
        .collect();
    let mut reserved = operations.clone();
    reserved.extend(resources.keys().cloned());
    let mut names = BTreeMap::new();
    for resource in resources.keys() {
        let mut name = resource.clone();
        if operations.contains(resource) {
            name.push_str("Resource");
            while reserved.contains(&name) {
                name.push_str("Resource");
            }
        }
        reserved.insert(name.clone());
        names.insert(resource.clone(), name);
    }
    names
}

fn resource_method_name(operation: &str, resource: &str) -> String {
    let singular = resource.strip_suffix('s').unwrap_or(resource);
    let mut method = operation;
    while let Some(shorter) = method
        .strip_prefix(resource)
        .or_else(|| method.strip_prefix(singular))
        .filter(|value| !value.is_empty() && value.len() < method.len())
    {
        method = shorter;
    }
    method
        .strip_suffix(resource)
        .or_else(|| method.strip_suffix(singular))
        .filter(|method| !method.is_empty())
        .unwrap_or(method)
        .into()
}

fn render_namespaced_operation(
    output: &mut String,
    api: &Api,
    resource: &str,
    facade: &str,
    method: &str,
    direct: &str,
    operation: &Operation,
) {
    let request = operation_request_name(api, operation);
    let has_input = !operation.parameters.is_empty() || operation.request_body.is_some();
    let parameters = if has_input {
        format!(", input *{request}")
    } else {
        String::new()
    };
    let result = match operation_response_kind(operation) {
        GoResponseKind::None => "error".to_owned(),
        GoResponseKind::Json(response) => format!("(*{response}, error)"),
        GoResponseKind::Text => "(string, error)".to_owned(),
        GoResponseKind::Binary => "([]byte, error)".to_owned(),
        GoResponseKind::EventStream => "(io.ReadCloser, error)".to_owned(),
    };
    let _ = writeln!(
        output,
        "// {method} invokes {direct} through the {resource} namespace.\nfunc (service *{facade}Service) {method}(ctx context.Context{parameters}) {result} {{"
    );
    if has_input {
        let _ = writeln!(output, "\treturn service.client.{direct}(ctx, input)\n}}\n");
    } else {
        let _ = writeln!(output, "\treturn service.client.{direct}(ctx)\n}}\n");
    }
}

fn render_readme(api: &Api, style: SdkClientStyle) -> String {
    let usage = match style {
        SdkClientStyle::Flat => "client.GetContact(ctx, input)",
        SdkClientStyle::Namespaced => "client.Contacts.Get(ctx, input)",
    };
    format!(
        "# {} Go SDK\n\nGenerated by Poolster. This package exposes the `{}` client style. Direct operations remain available in either mode. Generate with `SdkClientStyle::Flat` for `client.GetContact(...)`, or `SdkClientStyle::Namespaced` for resource-first calls such as `client.Contacts.Get(...)`.\n\n```go\nclient, err := NewClient(ClientConfig{{BaseURL: \"https://api.example.com\"}})\nif err != nil {{ panic(err) }}\n_ = {}\n```\n",
        api.name, usage, usage
    ) + include_str!("../templates/middleware.md.tmpl")
        + &page_pagination::documentation(api)
}

fn render_style_guide(api: &Api) -> String {
    format!(
        "# {} Go SDK styles\n\nPoolster supports two stable client surfaces:\n\n- `SdkClientStyle::Flat`: `client.GetContact(ctx, input)`\n- `SdkClientStyle::Namespaced`: `client.Contacts.Get(ctx, input)`\n\nThe namespaced surface is initialized by `NewClient` and delegates to the same typed operation methods, so both styles can coexist during migration.\n\n```go\nclient, err := NewClient(ClientConfig{{BaseURL: \"https://api.example.com\"}})\nif err != nil {{ panic(err) }}\ncontact, err := client.Contacts.Get(ctx, &GetContactRequest{{}})\n_ = contact\n_ = err\n```\n",
        api.name
    )
}

fn go_package_name(value: &str) -> String {
    let mut package = identifier_words(value)
        .into_iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<String>();
    if package.is_empty() {
        return package;
    }
    if package.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        package.insert(0, 'v');
    }
    match package.as_str() {
        "type" | "var" | "func" | "package" | "map" | "chan" | "interface" | "struct" | "go"
        | "defer" | "select" | "range" => format!("{package}sdk"),
        _ => package,
    }
}

fn go_module_name(value: &str) -> String {
    let slug = identifier_words(value)
        .into_iter()
        .map(|word| word.to_ascii_lowercase())
        .collect::<Vec<_>>()
        .join("-");
    if slug.is_empty() {
        "poolster/sdk".into()
    } else {
        slug
    }
}

fn go_type_name(value: &str) -> String {
    let mut name = identifier_words(value)
        .into_iter()
        .map(|word| go_exported_word(&word))
        .collect::<String>();
    if name.is_empty() {
        name = "Value".into();
    }
    if name.as_bytes().first().is_some_and(u8::is_ascii_digit) {
        name.insert(0, 'V');
    }
    name
}

fn go_exported_word(word: &str) -> String {
    match word.to_ascii_lowercase().as_str() {
        "api" => "API".into(),
        "id" => "ID".into(),
        "http" => "HTTP".into(),
        "https" => "HTTPS".into(),
        "json" => "JSON".into(),
        "oauth" => "OAuth".into(),
        "url" => "URL".into(),
        "uri" => "URI".into(),
        "uuid" => "UUID".into(),
        _ => {
            let mut chars = word.chars();
            match chars.next() {
                Some(first) => first.to_ascii_uppercase().to_string() + chars.as_str(),
                None => String::new(),
            }
        }
    }
}

fn identifier_words(value: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    for character in value.chars() {
        if character.is_ascii_alphanumeric() {
            if character.is_ascii_uppercase()
                && !current.is_empty()
                && current
                    .chars()
                    .last()
                    .is_some_and(|last| last.is_ascii_lowercase())
            {
                words.push(std::mem::take(&mut current));
            }
            current.push(character);
        } else if !current.is_empty() {
            words.push(std::mem::take(&mut current));
        }
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

